				FilteredListGreenStatusIndicatorTxt,	
				FilteredListGroupBy,
				IsHidden,
				ShowSearchBar,
				IsSearchDefaultCollapsed
              )
        VALUES
                (
                  @Guid,
                  @LanguageLabelID,
                  1,
                  @Code,
                  @GridDefinitionID,
                  @DetailPageUri,
