				FilteredListGreenStatusIndicatorTxt = @FilteredListGreenStatusIndicatorTxt,
				FilteredListGroupBy = @FilteredListGroupBy,
				IsHidden = @IsHidden,
				ShowSearchBar = @ShowSearchBar,
				IsSearchDefaultCollapsed = @IsSearchDefaultCollapsed
        WHERE
